class Base {
    virtual void process() { /* Base implementation */ }
};

class Derived : public Base {
    void process() override { /* Derived implementation */ }
    void call_modes() {
        // Standard virtual call: Requires VTable lookup at runtime
        // Target: Derived::process()
        process();

        // Explicit Qualification: Direct static call to specific target
        // Target: Base::process(). VTable bypassed.
        // Compiler optimization possible (known address at compile time).
        Base::process();
    }
};
